insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kurinoe-file-v-slivochno-chesnochnom-souse', 'main', false, null, 25, 320, 3, 'easy',
   '{"ru":"Куриное филе в сливочно-чесночном соусе","en":"Chicken breast in creamy garlic sauce","ua":"Куряче філе у вершково-часниковому соусі"}'::jsonb,
   '{"ru":"Нежное куриное филе в бархатистом сливочном соусе с чесноком и зеленью. Соус получается насыщенным, но лёгким — идеально с пастой, рисом или картофельным пюре.","en":"Tender chicken breast in a velvety cream sauce with garlic and herbs. The sauce is rich yet light — perfect over pasta, rice or mashed potatoes.","ua":"Ніжне куряче філе в оксамитовому вершковому соусі з часником і зеленню. Соус насичений, але легкий — ідеально з пастою, рисом чи картопляним пюре."}'::jsonb,
   '{"ru":["Куриное филе — 500 г","Сливки 20% — 200 мл","Чеснок — 3 зубчика","Сливочное масло — 20 г","Твёрдый сыр — 40 г","Петрушка — небольшой пучок","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Chicken breast — 500 g","Cream 20% — 200 ml","Garlic — 3 cloves","Butter — 20 g","Hard cheese — 40 g","Parsley — a small bunch","Salt — to taste","Black pepper — to taste"],"ua":["Куряче філе — 500 г","Вершки 20% — 200 мл","Часник — 3 зубчики","Вершкове масло — 20 г","Твердий сир — 40 г","Петрушка — невеликий пучок","Сіль — до смаку","Чорний перець — до смаку"]}'::jsonb,
   '{"ru":["Нарежьте филе на порционные кусочки, посолите и поперчите.","Обжарьте курицу на сливочном масле до румяности с обеих сторон.","Добавьте измельчённый чеснок, через минуту влейте сливки.","Всыпьте тёртый сыр и прогрейте соус до загустения.","Посыпьте петрушкой и подавайте. Совет: не кипятите сливки сильно, иначе соус расслоится."],"en":["Cut the fillet into portions and season with salt and pepper.","Sear the chicken in butter until golden on both sides.","Add minced garlic, then pour in the cream after a minute.","Stir in grated cheese and simmer until the sauce thickens.","Scatter with parsley and serve. Tip: don''t boil the cream hard or the sauce splits."],"ua":["Наріжте філе на порційні шматочки, посоліть і поперчіть.","Обсмажте курку на вершковому маслі до рум''яності з обох боків.","Додайте подрібнений часник, за хвилину влийте вершки.","Всипте тертий сир і прогрійте соус до загустіння.","Посипте петрушкою й подавайте. Порада: не кип''ятіть вершки сильно, інакше соус розшарується."]}'::jsonb,
   '{"ru":["ужин","курица","сливки","быстро"],"en":["dinner","chicken","cream","quick"],"ua":["вечеря","курка","вершки","швидко"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
