insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kuritsa-teriyaki', 'main', false, null, 20, 340, 3, 'easy',
   '{"ru":"Курица терияки с рисом","en":"Teriyaki chicken with rice","ua":"Курка теріякі з рисом"}'::jsonb,
   '{"ru":"Кусочки курицы в блестящей глазури терияки из соевого соуса, мёда и имбиря. Сладко-солёный вкус, липкий соус и кунжут сверху — азиатский ужин за 20 минут.","en":"Chicken pieces in a glossy teriyaki glaze of soy, honey and ginger. Sweet-savoury, sticky and finished with sesame — an Asian dinner in 20 minutes.","ua":"Шматочки курки в блискучій глазурі теріякі із соєвого соусу, меду й імбиру. Солодко-солоний смак, липкий соус і кунжут зверху — азійська вечеря за 20 хвилин."}'::jsonb,
   '{"ru":["Куриное филе — 500 г","Соевый соус — 4 ст. л.","Мёд — 2 ст. л.","Чеснок — 2 зубчика","Имбирь — 1 ч. л.","Растительное масло — 1 ст. л.","Кунжут — для подачи","Зелёный лук — для подачи","Рис — для подачи"],"en":["Chicken breast — 500 g","Soy sauce — 4 tbsp","Honey — 2 tbsp","Garlic — 2 cloves","Ginger — 1 tsp","Vegetable oil — 1 tbsp","Sesame seeds — to serve","Spring onion — to serve","Rice — to serve"],"ua":["Куряче філе — 500 г","Соєвий соус — 4 ст. л.","Мед — 2 ст. л.","Часник — 2 зубчики","Імбир — 1 ч. л.","Олія — 1 ст. л.","Кунжут — для подачі","Зелена цибуля — для подачі","Рис — для подачі"]}'::jsonb,
   '{"ru":["Нарежьте филе кубиками и обжарьте на масле до румяной корочки.","Смешайте соевый соус, мёд, чеснок и имбирь.","Влейте соус к курице и готовьте на среднем огне, помешивая.","Держите на огне, пока соус не загустеет и не покроет курицу глазурью.","Подавайте с рисом, посыпав кунжутом и зелёным луком."],"en":["Dice the fillet and fry in oil until golden.","Mix the soy sauce, honey, garlic and ginger.","Pour the sauce over the chicken and cook over medium heat, stirring.","Keep cooking until the sauce thickens and glazes the chicken.","Serve with rice, scattered with sesame and spring onion."],"ua":["Наріжте філе кубиками й обсмажте на олії до рум''яної скоринки.","Змішайте соєвий соус, мед, часник та імбир.","Влийте соус до курки й готуйте на середньому вогні, помішуючи.","Тримайте на вогні, поки соус не загусне й не вкриє курку глазур''ю.","Подавайте з рисом, посипавши кунжутом і зеленою цибулею."]}'::jsonb,
   '{"ru":["ужин","курица","терияки","азиатское"],"en":["dinner","chicken","teriyaki","asian"],"ua":["вечеря","курка","теріякі","азійське"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
