  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kurinye-bedra-medovo-gorchichnye', 'main', false, null, 45, 380, 4, 'easy',
   '{"ru":"Куриные бёдра в медово-горчичном соусе","en":"Honey-mustard baked chicken thighs","ua":"Курячі стегна в медово-гірчичному соусі"}'::jsonb,
   '{"ru":"Запечённые куриные бёдра с хрустящей карамельной корочкой из мёда и горчицы. Сочные внутри, ароматные снаружи — минимум усилий, максимум вкуса.","en":"Baked chicken thighs with a caramelised honey-mustard crust. Juicy inside, fragrant outside — minimal effort, maximum flavour.","ua":"Запечені курячі стегна з хрусткою карамельною скоринкою з меду й гірчиці. Соковиті всередині, ароматні зовні — мінімум зусиль, максимум смаку."}'::jsonb,
   '{"ru":["Куриные бёдра — 800 г","Мёд — 2 ст. л.","Горчица — 2 ст. л.","Соевый соус — 1 ст. л.","Чеснок — 3 зубчика","Оливковое масло — 1 ст. л.","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Chicken thighs — 800 g","Honey — 2 tbsp","Mustard — 2 tbsp","Soy sauce — 1 tbsp","Garlic — 3 cloves","Olive oil — 1 tbsp","Salt — to taste","Black pepper — to taste"],"ua":["Курячі стегна — 800 г","Мед — 2 ст. л.","Гірчиця — 2 ст. л.","Соєвий соус — 1 ст. л.","Часник — 3 зубчики","Оливкова олія — 1 ст. л.","Сіль — до смаку","Чорний перець — до смаку"]}'::jsonb,
   '{"ru":["Смешайте мёд, горчицу, соевый соус, чеснок и масло в маринад.","Обмажьте бёдра маринадом и оставьте на 15–20 минут.","Выложите в форму и запекайте при 200 °C около 35 минут.","Полейте бёдра соусом со дна формы и подрумяньте ещё 5 минут.","Совет: за 10 минут до конца полейте курицу соусом ещё раз — корочка будет ярче."],"en":["Mix honey, mustard, soy sauce, garlic and oil into a marinade.","Coat the thighs and let them sit for 15–20 minutes.","Arrange in a dish and bake at 200 °C for about 35 minutes.","Spoon the pan juices over the thighs and brown for 5 more minutes.","Tip: baste once more 10 minutes before the end for a deeper glaze."],"ua":["Змішайте мед, гірчицю, соєвий соус, часник і олію в маринад.","Обмажте стегна маринадом і залиште на 15–20 хвилин.","Викладіть у форму й запікайте за 200 °C близько 35 хвилин.","Полийте стегна соусом із дна форми й підрум''яньте ще 5 хвилин.","Порада: за 10 хвилин до кінця полийте курку соусом ще раз — скоринка буде яскравішою."]}'::jsonb,
   '{"ru":["ужин","курица","запечённое","мёд"],"en":["dinner","chicken","baked","honey"],"ua":["вечеря","курка","запечене","мед"]}'::jsonb)
