insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kuritsa-v-karri-s-kokosovym-molokom', 'main', false, null, 35, 400, 4, 'medium',
   '{"ru":"Курица в карри с кокосовым молоком","en":"Coconut curry chicken","ua":"Курка в карі з кокосовим молоком"}'::jsonb,
   '{"ru":"Ароматная курица в нежном соусе из кокосового молока с карри и специями. Пряно, но мягко — подавайте с рисом, чтобы собрать весь соус до капли.","en":"Fragrant chicken in a mild coconut-milk curry with warm spices. Spiced but gentle — serve with rice to soak up every drop of sauce.","ua":"Ароматна курка в ніжному соусі з кокосового молока з карі та спеціями. Пряно, але м''яко — подавайте з рисом, щоб зібрати весь соус до краплі."}'::jsonb,
   '{"ru":["Куриное филе — 600 г","Кокосовое молоко — 400 мл","Лук — 1 шт.","Карри — 1,5 ст. л.","Чеснок — 3 зубчика","Имбирь — 1 ч. л.","Помидоры в собственном соку — 200 г","Растительное масло — 1 ст. л.","Соль — по вкусу"],"en":["Chicken breast — 600 g","Coconut milk — 400 ml","Onion — 1","Curry powder — 1.5 tbsp","Garlic — 3 cloves","Ginger — 1 tsp","Canned tomatoes — 200 g","Vegetable oil — 1 tbsp","Salt — to taste"],"ua":["Куряче філе — 600 г","Кокосове молоко — 400 мл","Цибуля — 1 шт.","Карі — 1,5 ст. л.","Часник — 3 зубчики","Імбир — 1 ч. л.","Помідори у власному соку — 200 г","Олія — 1 ст. л.","Сіль — до смаку"]}'::jsonb,
   '{"ru":["Обжарьте нарезанный лук с чесноком и имбирём до мягкости.","Всыпьте карри и прогрейте 30 секунд до аромата.","Добавьте нарезанную курицу и обжарьте до побеления.","Влейте помидоры и кокосовое молоко, тушите 15–20 минут.","Посолите и дайте соусу загустеть. Подавайте с рисом."],"en":["Fry the chopped onion with garlic and ginger until soft.","Add the curry powder and toast for 30 seconds until fragrant.","Add the diced chicken and fry until it turns white.","Pour in the tomatoes and coconut milk, simmer 15–20 minutes.","Season and let the sauce thicken. Serve with rice."],"ua":["Обсмажте нарізану цибулю з часником та імбиром до м''якості.","Всипте карі й прогрійте 30 секунд до аромату.","Додайте нарізану курку й обсмажте до побіління.","Влийте помідори й кокосове молоко, тушкуйте 15–20 хвилин.","Посоліть і дайте соусу загуснути. Подавайте з рисом."]}'::jsonb,
   '{"ru":["ужин","курица","карри","кокос"],"en":["dinner","chicken","curry","coconut"],"ua":["вечеря","курка","карі","кокос"]}'::jsonb)
