insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kurinye-shashlychki-v-duhovke', 'main', true, null, 40, 220, 4, 'easy',
   '{"ru":"Куриные шашлычки в духовке","en":"Oven-baked chicken skewers","ua":"Курячі шашлички в духовці"}'::jsonb,
   '{"ru":"Сочные кусочки курицы на шпажках в лёгком йогуртовом маринаде, запечённые до румяной корочки. ПП-вариант шашлыка без мангала — вкусно и по-домашнему просто.","en":"Juicy chicken pieces on skewers in a light yoghurt marinade, baked until golden. A healthy no-grill kebab — tasty and easy to make at home.","ua":"Соковиті шматочки курки на шпажках у легкому йогуртовому маринаді, запечені до рум''яної скоринки. ПХ-варіант шашлику без мангала — смачно й по-домашньому просто."}'::jsonb,
   '{"ru":["Куриное филе — 700 г","Натуральный йогурт — 150 г","Паприка — 1 ч. л.","Чеснок — 3 зубчика","Лимонный сок — 1 ст. л.","Оливковое масло — 1 ст. л.","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Chicken breast — 700 g","Plain yoghurt — 150 g","Paprika — 1 tsp","Garlic — 3 cloves","Lemon juice — 1 tbsp","Olive oil — 1 tbsp","Salt — to taste","Black pepper — to taste"],"ua":["Куряче філе — 700 г","Натуральний йогурт — 150 г","Паприка — 1 ч. л.","Часник — 3 зубчики","Лимонний сік — 1 ст. л.","Оливкова олія — 1 ст. л.","Сіль — до смаку","Чорний перець — до смаку"]}'::jsonb,
   '{"ru":["Нарежьте филе крупными кубиками.","Смешайте йогурт, паприку, чеснок, лимонный сок и масло; замаринуйте курицу 20–30 минут.","Нанижите кусочки на шпажки.","Запекайте при 210 °C около 20–25 минут, перевернув один раз.","Совет: замочите деревянные шпажки в воде, чтобы не подгорели."],"en":["Cut the fillet into large cubes.","Mix yoghurt, paprika, garlic, lemon juice and oil; marinate the chicken 20–30 minutes.","Thread the pieces onto skewers.","Bake at 210 °C for about 20–25 minutes, turning once.","Tip: soak wooden skewers in water so they don''t scorch."],"ua":["Наріжте філе великими кубиками.","Змішайте йогурт, паприку, часник, лимонний сік і олію; замаринуйте курку 20–30 хвилин.","Нанижіть шматочки на шпажки.","Запікайте за 210 °C близько 20–25 хвилин, перевернувши один раз.","Порада: замочіть дерев''яні шпажки у воді, щоб не підгоріли."]}'::jsonb,
   '{"ru":["ПП","ужин","курица","духовка"],"en":["healthy","dinner","chicken","oven"],"ua":["ПХ","вечеря","курка","духовка"]}'::jsonb)
