insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kuritsa-stir-fray-s-ovoschami', 'main', true, null, 20, 260, 3, 'easy',
   '{"ru":"Курица стир-фрай с овощами","en":"Chicken and vegetable stir-fry","ua":"Курка стір-фрай з овочами"}'::jsonb,
   '{"ru":"Быстрая обжарка курицы с хрустящими овощами в соево-имбирном соусе на сильном огне. Овощи остаются яркими и хрустящими, а ужин готов за 20 минут.","en":"A fast sear of chicken with crisp vegetables in a soy-ginger sauce over high heat. The veg stays bright and crunchy, and dinner is ready in 20 minutes.","ua":"Швидке обсмажування курки з хрусткими овочами в соєво-імбирному соусі на сильному вогні. Овочі лишаються яскравими й хрусткими, а вечеря готова за 20 хвилин."}'::jsonb,
   '{"ru":["Куриное филе — 400 г","Болгарский перец — 1 шт.","Брокколи — 200 г","Морковь — 1 шт.","Соевый соус — 3 ст. л.","Чеснок — 2 зубчика","Имбирь — 1 ч. л.","Растительное масло — 2 ст. л."],"en":["Chicken breast — 400 g","Bell pepper — 1","Broccoli — 200 g","Carrot — 1","Soy sauce — 3 tbsp","Garlic — 2 cloves","Ginger — 1 tsp","Vegetable oil — 2 tbsp"],"ua":["Куряче філе — 400 г","Болгарський перець — 1 шт.","Броколі — 200 г","Морква — 1 шт.","Соєвий соус — 3 ст. л.","Часник — 2 зубчики","Імбир — 1 ч. л.","Олія — 2 ст. л."]}'::jsonb,
   '{"ru":["Нарежьте курицу и овощи тонкими полосками.","Обжарьте курицу на сильном огне до румяности и уберите со сковороды.","Быстро обжарьте овощи 3–4 минуты, чтобы остались хрустящими.","Верните курицу, добавьте чеснок, имбирь и соевый соус.","Прогрейте всё вместе минуту и сразу подавайте."],"en":["Slice the chicken and vegetables into thin strips.","Sear the chicken over high heat until golden and remove.","Stir-fry the vegetables 3–4 minutes so they stay crisp.","Return the chicken, add garlic, ginger and soy sauce.","Toss together for a minute and serve at once."],"ua":["Наріжте курку й овочі тонкими смужками.","Обсмажте курку на сильному вогні до рум''яності й приберіть зі сковороди.","Швидко обсмажте овочі 3–4 хвилини, щоб лишилися хрусткими.","Поверніть курку, додайте часник, імбир і соєвий соус.","Прогрійте все разом хвилину й одразу подавайте."]}'::jsonb,
   '{"ru":["ПП","ужин","курица","овощи"],"en":["healthy","dinner","chicken","vegetables"],"ua":["ПХ","вечеря","курка","овочі"]}'::jsonb)
