insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kurinyy-shnitsel-v-panirovke', 'main', false, null, 25, 360, 3, 'easy',
   '{"ru":"Куриный шницель в панировке","en":"Crispy chicken schnitzel","ua":"Курячий шніцель у паніровці"}'::jsonb,
   '{"ru":"Тонкие отбивные из куриного филе в золотистой хрустящей панировке. Снаружи хрустит, внутри остаётся сочным — классика, которую любят и взрослые, и дети.","en":"Thin chicken breast cutlets in a golden, crunchy crust. Crisp outside, juicy inside — a classic loved by kids and grown-ups alike.","ua":"Тонкі відбивні з курячого філе в золотистій хрусткій паніровці. Зовні хрустить, всередині лишається соковитим — класика, яку люблять і дорослі, і діти."}'::jsonb,
   '{"ru":["Куриное филе — 500 г","Яйца — 2 шт.","Панировочные сухари — 100 г","Мука — 3 ст. л.","Соль — по вкусу","Чёрный перец — по вкусу","Масло для жарки — по необходимости"],"en":["Chicken breast — 500 g","Eggs — 2","Breadcrumbs — 100 g","Flour — 3 tbsp","Salt — to taste","Black pepper — to taste","Oil for frying — as needed"],"ua":["Куряче філе — 500 г","Яйця — 2 шт.","Панірувальні сухарі — 100 г","Борошно — 3 ст. л.","Сіль — до смаку","Чорний перець — до смаку","Олія для смаження — за потреби"]}'::jsonb,
   '{"ru":["Разрежьте филе вдоль и слегка отбейте, посолите и поперчите.","Обваляйте кусочки в муке, затем во взбитом яйце и в сухарях.","Обжарьте на среднем огне по 3–4 минуты с каждой стороны до золотистой корочки.","Выложите на бумажное полотенце, чтобы убрать лишнее масло.","Совет: не перегревайте масло, иначе панировка сгорит раньше, чем прожарится мясо."],"en":["Slice the fillet lengthways, gently flatten, then season.","Coat the pieces in flour, then beaten egg, then breadcrumbs.","Fry over medium heat 3–4 minutes per side until golden.","Drain on paper towel to remove excess oil.","Tip: don''t overheat the oil or the crust burns before the meat cooks."],"ua":["Розріжте філе вздовж і злегка відбийте, посоліть і поперчіть.","Обваляйте шматочки в борошні, потім у збитому яйці та в сухарях.","Обсмажте на середньому вогні по 3–4 хвилини з кожного боку до золотистої скоринки.","Викладіть на паперовий рушник, щоб прибрати зайву олію.","Порада: не перегрівайте олію, інакше паніровка згорить раніше, ніж просмажиться м''ясо."]}'::jsonb,
